// 原始家系和禀赋目录严格受检；没有隐式默认人物、推测亲代或自由技能加成。
#include "family_lineage.hpp"
#include "succession_personal_assets.hpp"
#include "resident/storage/common_checkpoint.hpp"
namespace hanmo::resident {namespace {
// 有限四档分布，错长度及非整数值不进入概率规则。
std::array<Integer,4> four(const BoundaryValue& value){const auto& items=boundary::array(value,"innate/four");if(items.size()!=4)boundary::fail("InvalidInnateFourLevels","");std::array<Integer,4> out{};for(std::size_t i=0;i<4;++i)out[i]=boundary::integer(items[i],"innate/four");return out;}
// 所有父母组合概率显式提供，未知策略不能退回看似可用的默认值。
InnateInheritanceWeights weights(const BoundaryValue& value){using namespace boundary;fields(value,{"absent","retained","strengthened"},{},"innate/weights");return {get_int(value,"absent",""),get_int(value,"retained",""),get_int(value,"strengthened","")};}
}
Outcome<FamilyLineageCatalog> decode_family_lineage_catalog(const BoundaryValue& input){try{using namespace boundary;auto unique=validate_succession_json_unique(input);if(!unique.ok)return {false,{},unique.error};fields(input,{"version","profile","origins","original_innate_levels","endowment"},{},"family_lineage");if(get_int(input,"version","")!=1||get_string(input,"profile","")!="biological_origin_innate_v1")unsupported("UnsupportedFamilyLineageProfile","family_lineage");FamilyLineageCatalog out;out.enabled=true;
    for(const auto& row:object(field(input,"origins",""),"lineage/origins")){fields(row.second,{"actor_id","parent_actor_ids"},{},"lineage/origin");BiologicalOrigin origin;origin.actor_id=get_string(row.second,"actor_id","");for(const auto& value:array(field(row.second,"parent_actor_ids",""),"lineage/parents"))origin.parent_actor_ids.push_back(string(value,"lineage/parent"));if(row.first!=origin.actor_id||origin.parent_actor_ids.size()>2||!out.origins.insert(row.first,std::move(origin)))fail("InvalidBiologicalOrigin",row.first);}
    for(const auto& row:object(field(input,"original_innate_levels",""),"lineage/innate")){OrderedTable<Integer> levels;for(const auto& item:object(row.second,"lineage/levels"))if(!levels.insert(item.first,integer(item.second,"lineage/level")))fail("DuplicateOriginalInnateLevel",row.first);if(levels.size()>16||!out.original_innate_levels.insert(row.first,std::move(levels)))fail("InvalidOriginalInnateActor",row.first);}
    const auto& endowment=field(input,"endowment","");fields(endowment,{"version","unweighted","single","different","same","families"},{},"lineage/endowment");out.endowment.version=get_string(endowment,"version","");out.endowment.unweighted=four(field(endowment,"unweighted",""));out.endowment.single=weights(field(endowment,"single",""));out.endowment.different=weights(field(endowment,"different",""));out.endowment.same=weights(field(endowment,"same",""));for(const auto& row:object(field(endowment,"families",""),"lineage/families")){fields(row.second,{"id","learning_skill_ids","learning_bonus_bp"},{},"lineage/family");InnateFamilyDefinition family;family.id=get_string(row.second,"id","");for(const auto& value:array(field(row.second,"learning_skill_ids",""),"lineage/skills"))family.learning_skill_ids.push_back(string(value,"lineage/skill"));family.learning_bonus_bp=four(field(row.second,"learning_bonus_bp",""));if(row.first!=family.id||!out.endowment.families.insert(row.first,std::move(family)))fail("InvalidInnateFamily",row.first);}if(out.origins.size()>4096||out.original_innate_levels.size()>4096)fail("FamilyLineageCatalogLimit","");auto valid=validate_birth_endowment_policy(out.endowment,true);return valid.ok?Outcome<FamilyLineageCatalog>{true,std::move(out),{}}:Outcome<FamilyLineageCatalog>{false,{},valid.error};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
